), inserted AS (
 INSERT INTO pathways(career_id,title,description,pathway_type,record_status,verification_status)
 SELECT c.id,p.title,p.description,'template','published','needs_review' FROM pathway_seed p JOIN careers c ON c.title=p.career_title
 WHERE NOT EXISTS (SELECT 1 FROM pathways old WHERE old.career_id=c.id AND old.title=p.title)
 RETURNING id,career_id,title
) SELECT 1;
