) INSERT INTO pathway_steps(pathway_id,step_order,title,description,step_type,metadata)
SELECT p.id,x.step_order,x.title,x.description,x.step_type,x.metadata
FROM stage_seed x JOIN careers c ON c.title=x.career_title JOIN pathways p ON p.career_id=c.id AND p.title=c.title || ' — Foundations to Portfolio'
WHERE NOT EXISTS (SELECT 1 FROM pathway_steps old WHERE old.pathway_id=p.id AND old.step_order=x.step_order)
ON CONFLICT (pathway_id,step_order) DO NOTHING;

-- 5. Three career-specific project templates per role (starter, practical, career-ready)
INSERT INTO career_projects (career_id, career_title, title, slug, difficulty_level, difficulty_label, project_type, estimated_effort, brief, problem_statement, learning_objectives, prerequisites, tasks, deliverables, acceptance_criteria, evaluation_rubric, skills, starter_template, reflection_prompts, next_step, origin, verification_status)
SELECT c.id, x.career_title, x.title, x.slug, x.level, x.label, x.project_type, x.effort, x.brief, x.problem, x.objectives::jsonb, x.prerequisites::jsonb, x.tasks::jsonb, x.deliverables::jsonb, x.acceptance::jsonb, x.rubric::jsonb, x.skills::jsonb, x.starter::jsonb, x.reflections::jsonb, x.next_step, 'curated', 'verified'
FROM (VALUES
('Frontend Developer','Frontend Developer: Practical Baseline Deliverable','frontend-developer-starter-1',1,'Starter','technical','1–2 weeks','Build a small, focused artifact that demonstrates foundational skills. Target career: Frontend Developer.','Create a clear baseline solution for a common beginner-level problem in this career area.','["Apply programming fundamentals in a role-relevant context", "Apply object-oriented programming in a role-relevant context", "Apply data structures and algorithms in a role-relevant context", "Explain decisions and document evidence"]','["Basic orientation to the target career area"]','["Define the problem and intended audience", "Identify assumptions and gather sample inputs", "Build the smallest useful solution", "Test or review the result", "Write a short reflection"]','["A working artifact or documented case", "A short README or process note", "Evidence of testing or review"]','["The artifact addresses the stated problem", "Key decisions and assumptions are documented", "The result is understandable to another person"]','["Problem framing", "Execution quality", "Documentation"]','["Programming Fundamentals", "Object-Oriented Programming", "Data Structures and Algorithms", "Git and Version Control", "Software Design", "Debugging"]','{"domain": "software_development", "template_notice": "Illustrative learning project; adapt to the learner and never represent it as completed work.", "career_title": "Frontend Developer"}','["What did you learn? What would you change next?", "What would you ask a subject-matter expert to review?"]','Use the resulting artifact as evidence in the learner portfolio and compare it against real role requirements.'),
('Frontend Developer','Frontend Developer: Real-World Workflow Case Study','frontend-developer-practical-2',2,'Practical','technical','3–5 weeks','Deliver a realistic multi-step solution that combines several role competencies. Target career: Frontend Developer.','Address a realistic workflow or stakeholder need using a structured process and measurable criteria.','["Apply programming fundamentals in a role-relevant context", "Apply object-oriented programming in a role-relevant context", "Apply data structures and algorithms in a role-relevant context", "Explain decisions and document evidence"]','["Completion of a starter artifact or equivalent experience"]','["Gather requirements or context", "Plan the workflow and success criteria", "Build or execute the solution in iterations", "Collect feedback or validate against criteria", "Document limitations and improvements"]','["End-to-end artifact or case study", "Process/workflow documentation", "Validation results and improvement notes"]','["The solution covers the main workflow", "Validation is recorded", "Trade-offs and limitations are explained"]','["Problem solving", "Domain competence", "Validation and iteration"]','["Programming Fundamentals", "Object-Oriented Programming", "Data Structures and Algorithms", "Git and Version Control", "Software Design", "Debugging"]','{"domain": "software_development", "template_notice": "Illustrative learning project; adapt to the learner and never represent it as completed work.", "career_title": "Frontend Developer"}','["Which feedback changed your approach? Which assumptions remain?", "What would you ask a subject-matter expert to review?"]','Use the resulting artifact as evidence in the learner portfolio and compare it against real role requirements.'),
